"""Comment once on every open PR that is stuck: no checks, conflicted, or green and unmerged.

One comment per (state, head sha), marked with an HTML comment so a later run never repeats it.
A new push changes the head and earns a fresh look. Drafts are skipped. Runs under the workflow
token from pr-watch.yml; needs `gh` on the runner and nothing else.
"""
import datetime as dt
import json
import os
import subprocess
import sys

NO_CHECKS_AFTER = dt.timedelta(minutes=10)
GREEN_UNMERGED_AFTER = dt.timedelta(hours=2)
FOOTER = "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_"


def gh(path, *args):
    out = subprocess.run(["gh", "api", path, *args], capture_output=True, text=True)
    if out.returncode:
        print(f"gh api {path} failed: {out.stderr.strip()}", file=sys.stderr)
        return None
    return json.loads(out.stdout) if out.stdout.strip() else None


def when(stamp):
    return dt.datetime.fromisoformat(stamp.replace("Z", "+00:00"))


def main():
    repo = os.environ["GITHUB_REPOSITORY"]
    now = dt.datetime.now(dt.timezone.utc)
    prs = gh(f"/repos/{repo}/pulls?state=open&per_page=50") or []
    for brief in prs:
        if brief.get("draft"):
            continue
        number = brief["number"]
        pr = gh(f"/repos/{repo}/pulls/{number}") or brief
        sha = pr["head"]["sha"]
        state, message = None, None

        if pr.get("mergeable_state") == "dirty":
            state = "conflict"
            message = (f"This PR conflicts with `{pr['base']['ref']}`, so CI will not run on it. "
                       "Merge the base branch in and push.")
        else:
            runs = gh(f"/repos/{repo}/commits/{sha}/check-runs?per_page=100") or {}
            check_runs = runs.get("check_runs", [])
            pushed = when(pr["updated_at"])
            if not check_runs:
                if now - pushed > NO_CHECKS_AFTER:
                    state = "no-checks"
                    message = (f"No checks have started on `{sha[:7]}` after "
                               f"{int((now - pushed).total_seconds() // 60)} minutes. "
                               "Check the PR is mergeable and that a workflow matches this branch.")
            else:
                done = [c for c in check_runs if c["status"] == "completed"]
                if len(done) == len(check_runs) and all(
                    c["conclusion"] in ("success", "skipped", "neutral") for c in done
                ):
                    finished = max(when(c["completed_at"]) for c in done)
                    if now - finished > GREEN_UNMERGED_AFTER:
                        hours = (now - finished).total_seconds() / 3600
                        state = "green-unmerged"
                        message = (f"CI has been green on `{sha[:7]}` for {hours:.1f} hours and the PR is "
                                   "still open. Merge it, hand it to the shipping thread, or say what it waits on.")

        if not state:
            continue
        marker = f"<!-- pr-watch:{state}:{sha} -->"
        comments = gh(f"/repos/{repo}/issues/{number}/comments?per_page=100") or []
        if any(marker in (c.get("body") or "") for c in comments):
            continue
        body = f"{marker}\n**PR watch:** {message}{FOOTER}"
        gh(f"/repos/{repo}/issues/{number}/comments", "-X", "POST", "-f", f"body={body}")
        print(f"#{number}: {state} on {sha[:7]}")


if __name__ == "__main__":
    main()
